-- Load Parquet files from Cloud Storage into a table (free load job)
LOAD DATA INTO shop.orders
FROM FILES (
  format = 'PARQUET',
  uris = ['gs://my-bucket/orders/2025-06-*.parquet']
);

-- Query CSV files in place without loading
CREATE OR REPLACE EXTERNAL TABLE shop.ext_returns
OPTIONS (format = 'CSV', uris = ['gs://my-bucket/returns/*.csv'], skip_leading_rows = 1);

SELECT COUNT(*) FROM shop.ext_returns;

-- Export query results back to Cloud Storage
EXPORT DATA OPTIONS (
  uri = 'gs://my-bucket/exports/big_orders_*.parquet',
  format = 'PARQUET', overwrite = true
) AS
SELECT * FROM shop.orders WHERE amount > 1000;

-- CLI equivalent of the load:
-- bq load --source_format=PARQUET shop.orders "gs://my-bucket/orders/2025-06-*.parquet"

-- Upsert a batch of changes from a staging table
MERGE shop.customers AS t
USING shop.customers_staging AS s
ON t.id = s.id
WHEN MATCHED AND s.deleted THEN
  DELETE
WHEN MATCHED THEN
  UPDATE SET email = s.email, plan = s.plan, updated_at = s.updated_at
WHEN NOT MATCHED AND NOT s.deleted THEN
  INSERT (id, email, plan, updated_at) VALUES (s.id, s.email, s.plan, s.updated_at);

-- Atomic multi-table change
BEGIN TRANSACTION;
  INSERT INTO shop.orders_archive SELECT * FROM shop.orders WHERE status = 'closed';
  DELETE FROM shop.orders WHERE status = 'closed';
COMMIT TRANSACTION;

UPDATE shop.customers SET plan = 'free' WHERE TRUE;   -- WHERE is mandatory

DECLARE run_date DATE DEFAULT DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY);
DECLARE n INT64;

BEGIN
  CREATE TEMP TABLE daily AS
  SELECT user_id, COUNT(*) AS events
  FROM web.events
  WHERE DATE(event_ts) = run_date
  GROUP BY user_id;

  SET n = (SELECT COUNT(*) FROM daily);
  IF n = 0 THEN
    RAISE USING MESSAGE = FORMAT('No events for %t', run_date);
  END IF;

  EXECUTE IMMEDIATE FORMAT(
    'CREATE OR REPLACE TABLE web.daily_%s AS SELECT * FROM daily',
    FORMAT_DATE('%Y%m%d', run_date));
EXCEPTION WHEN ERROR THEN
  SELECT 'failed: ' || @@error.message AS status;
END;

CREATE TEMP FUNCTION net_price(gross NUMERIC, vat NUMERIC) AS (
  ROUND(gross / (1 + vat), 2)
);

CREATE TEMP FUNCTION domain_of(email STRING) AS (
  LOWER(SPLIT(email, '@')[SAFE_OFFSET(1)])
);

CREATE TEMP FUNCTION title_case(s STRING)
RETURNS STRING
LANGUAGE js AS r"""
  return s.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
""";

SELECT net_price(121, NUMERIC '0.21')   AS net,     -- 100
       domain_of('Ana@Example.COM')     AS domain,  -- example.com
       title_case('hello big query')    AS title;   -- Hello Big Query

-- What did the table look like an hour ago?
SELECT COUNT(*)
FROM shop.orders FOR SYSTEM_TIME AS OF TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 1 HOUR);

-- Restore after a bad DELETE: rebuild from the earlier version
CREATE OR REPLACE TABLE shop.orders_restored AS
SELECT * FROM shop.orders
FOR SYSTEM_TIME AS OF TIMESTAMP '2025-06-01 09:00:00+00';

-- Cheap, read-only point-in-time snapshot (kept 30 days)
CREATE SNAPSHOT TABLE backups.orders_20250601
CLONE shop.orders
OPTIONS (expiration_timestamp = TIMESTAMP_ADD(CURRENT_TIMESTAMP(), INTERVAL 30 DAY));

-- Writable clone for testing a migration
CREATE TABLE sandbox.orders_test CLONE shop.orders;

-- Shorten the time-travel window of a high-churn staging dataset
ALTER SCHEMA staging SET OPTIONS (max_time_travel_hours = 48);
